# -*- coding: utf-8 -*-
"""V14 runtime resource lookup with frozen/non-frozen support."""
from __future__ import annotations
import base64
import io
import sys
from pathlib import Path

# Tiny embedded fallback so the author avatar still works if a packaging tool
# places data under a different directory. Build-time assets remain the primary source.
_AVATAR_B64 = ""  # populated by build script at source creation time

def candidate_roots() -> list[Path]:
    roots: list[Path] = []
    try:
        roots.append(Path(sys.executable).resolve().parent)
    except Exception:
        pass
    try:
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            roots.append(Path(meipass))
    except Exception:
        pass
    try:
        roots.append(Path(__file__).resolve().parent)
    except Exception:
        pass
    # preserve order, remove duplicates
    out=[]
    seen=set()
    for root in roots:
        s=str(root)
        if s not in seen:
            seen.add(s); out.append(root)
    return out

def asset_path(relative: str) -> Path | None:
    rel=Path(relative)
    for root in candidate_roots():
        p=root/rel
        if p.is_file():
            return p
    return None

def load_avatar_image():
    from PIL import Image
    p=asset_path("assets/edgar_avatar.png")
    if p:
        return Image.open(p).convert("RGBA")
    if _AVATAR_B64:
        data=base64.b64decode(_AVATAR_B64)
        return Image.open(io.BytesIO(data)).convert("RGBA")
    return None
